// The source groups requirements by broad topics. Keep its wording while
// assigning each requirement to the individual Toán 6 lesson.
(function splitToan6TopicWideYccd(){
  const rows = KHBD_YCCD.toan && KHBD_YCCD.toan["6"];
  if (!Array.isArray(rows)) return;
  rows.forEach(row => {
    const override = KHBD_LESSON_YCCD_OVERRIDES[lessonNumber(row.lesson)];
    if (override) row.items = override.slice();
  });
})();

function getOfficialYccd({ subjectId, grade, topic, visionText } = {}) {
  const subject = String(subjectId || "").toLowerCase();
  if (subject !== "toan" && subject !== "math") return "";
  const gradeKey = String(grade || "");
  const picked = findOfficialYccdRows({ subjectId, grade, topic, visionText });
  if (!picked.length) return "";

  const lines = [
    "Nguồn bắt buộc: Yêu cầu cần đạt môn Toán 6–12 – CTGDPT 2018.xlsx, lớp " + gradeKey + ".",
    "Căn cứ pháp lý: Chương trình GDPT 2018 ban hành kèm Thông tư 32/2018/TT-BGDĐT. Chỉ dùng nguyên văn các YCCĐ dưới đây; không thêm kiến thức ngoài danh sách."
  ];
  picked.forEach(row => {
    lines.push("Bài SGK: " + row.lesson);
    lines.push("Nội dung CTGDPT 2018 tham chiếu: " + row.topic);
    row.items.forEach(item => lines.push("- " + item));
  });
  return lines.join("\n");
}

function getCurrentCurriculumNotice({ subjectId, grade } = {}) {
  const subject = String(subjectId || "").toLowerCase();
  const gradeKey = String(grade || "");
  const amendment = KHBD_CURRICULUM_AMENDMENTS[subject] && KHBD_CURRICULUM_AMENDMENTS[subject][gradeKey];
  if (amendment) {
    return "Căn cứ cập nhật: " + amendment + " Không dùng YCCĐ cũ nếu mâu thuẫn với Thông tư 17/2025/TT-BGDĐT.";
  }
  return "Căn cứ cập nhật: CT GDPT 2018/Thông tư 32/2018/TT-BGDĐT, các sửa đổi liên quan còn hiệu lực. TT 17/2025/TT-BGDĐT không sửa YCCĐ của môn này ở cấp THCS.";
}

if (typeof window !== "undefined") {
  window.KHBD_YCCD = KHBD_YCCD;
  window.KHBD_CURRICULUM_AMENDMENTS = KHBD_CURRICULUM_AMENDMENTS;
  window.getOfficialYccd = getOfficialYccd;
  window.getCleanOfficialYccd = getCleanOfficialYccd;
  window.findOfficialYccdRows = findOfficialYccdRows;
  window.generatePedagogicalOutcome = generatePedagogicalOutcome;
  window.getCurrentCurriculumNotice = getCurrentCurriculumNotice;
}
if (typeof globalThis !== "undefined") {
  globalThis.KHBD_YCCD = KHBD_YCCD;
}
if (typeof module !== "undefined" && module.exports) {
  module.exports = { KHBD_YCCD, KHBD_CURRICULUM_AMENDMENTS, getOfficialYccd, getCleanOfficialYccd, findOfficialYccdRows, generatePedagogicalOutcome, getCurrentCurriculumNotice };
}

